/* Independent teaching workspace; credentials remain owned by the existing AI module. */
window.createCampusTeaching=function(ctx){
  'use strict';
  const {state,school,esc,icon,heading,footer,navigate,renderPage,toast,showModal,closeModal,ai}=ctx;
  const Core=window.TeachingCore,Media=window.TeachingMedia,$=s=>document.querySelector(s),key='xueyu-teaching-v1';
  const defaults=()=>({topic:'',audience:'大学 / 自主学习',objectives:'',material:'',output:'both',minutes:3,blocks:Core.blocks.filter(([id])=>['goals','concepts','examples','mistakes','practice','answers','summary','sources'].includes(id)).map(([id,title])=>({id,title})),prices:{input:2,output:8,speech:0.8},budget:1,ttsModel:'',voice:''});
  const drafts=new Map(),results=new Map(),audio=new Map(),video=new Map();let tab='create',operation=null,error='',progress='',generation=0,slideIndex=0;
  let history={};try{const saved=JSON.parse(localStorage.getItem(key)||'{}');if(saved&&typeof saved==='object'&&!Array.isArray(saved))history=saved;}catch{}
  const draft=()=>{if(!drafts.has(school().id))drafts.set(school().id,defaults());return drafts.get(school().id);};
  const result=()=>results.get(school().id)||null;
  const list=()=>Array.isArray(history[school().id])?history[school().id].filter(r=>r&&typeof r.id==='string'&&typeof r.lesson?.title==='string'&&Array.isArray(r.lesson.sections)&&Array.isArray(r.lesson.slides)&&Array.isArray(r.config?.blocks)&&['pdf','video','both'].includes(r.config.output)&&Number.isFinite(r.created)).slice(0,6):[];
  const busy=()=>Boolean(operation),disabled=()=>busy()?'disabled':'';
  function saveHistory(){try{localStorage.setItem(key,JSON.stringify(history));}catch{toast('浏览器存储已满，成果仍保留在本页，请先导出。');}}
  function remember(record){history[school().id]=[record,...list().filter(r=>r.id!==record.id)].slice(0,6);saveHistory();}
  function clearVideo(id){const item=video.get(id);if(item)URL.revokeObjectURL(item.url);video.delete(id);}
  function resetMedia(){const id=result()?.id;if(id){clearVideo(id);audio.delete(id);}window.speechSynthesis?.cancel();}
  function rerender(){if(state.route==='teaching')renderPage();}
  const formatLabel=mode=>({pdf:'PDF 讲义',video:'授课视频',both:'视频＋讲义'})[mode]||'教学内容';
  function entry(){return `<button class="teach-entry" data-route="teaching"><span class="teach-entry-symbol">${icon('graduation')}</span><span><strong>AI 学堂</strong><small>一个主题，变成一节课 · 视频与讲义自由选</small></span><span class="teach-entry-tag">新功能</span>${icon('arrow')}</button>`;}
  function form(){const d=draft();return `<div class="teach-workspace"><form id="teach-create-form" class="teach-form">
    <section class="teach-card"><div class="teach-step"><span>01</span><div><h2>这次，想讲清楚什么？</h2><p>从一个知识点出发，也可以带上已有资料。</p></div></div>
    <label class="form-label" for="teach-topic">教学主题</label><input class="form-input" id="teach-topic" name="topic" value="${esc(d.topic)}" maxlength="100" placeholder="例如：用生活中的例子讲解一次函数" required ${disabled()}/>
    <div class="teach-pair"><div><label class="form-label" for="teach-audience">面向谁讲解</label><select class="form-input" id="teach-audience" name="audience" ${disabled()}>${['小学','初中','高中','大学 / 自主学习','职业技能培训'].map(v=>`<option ${d.audience===v?'selected':''}>${v}</option>`).join('')}</select></div><div><label class="form-label" for="teach-minutes">课程时长</label><select class="form-input" id="teach-minutes" name="minutes" ${disabled()}>${[3,5].map(v=>`<option value="${v}" ${Number(d.minutes)===v?'selected':''}>${v} 分钟 · 微课</option>`).join('')}</select></div></div>
    <label class="form-label" for="teach-objectives">学习目标 <small>选填</small></label><textarea class="form-input" id="teach-objectives" name="objectives" rows="2" maxlength="600" placeholder="学完后，希望学生理解什么、能解决什么问题？" ${disabled()}>${esc(d.objectives)}</textarea>
    <details class="teach-materials" ${d.material?'open':''}><summary>${icon('book')}带上参考资料 <span>粘贴文字 / 导入 TXT、MD</span></summary><textarea class="form-input" id="teach-material" name="material" rows="5" maxlength="12000" aria-label="参考资料" placeholder="粘贴教材片段、笔记或你信任的资料，并附上来源。最多 12000 字。" ${disabled()}>${esc(d.material)}</textarea><label class="teach-file-label">${icon('upload')}导入文字资料<input id="teach-source-file" type="file" accept=".txt,.md,text/plain,text/markdown" ${disabled()}/></label><small>生成时仅将这里的资料和教学要求发送给所选模型。当前版本不自动联网检索，也不读取其他校园数据。</small></details></section>
    <section class="teach-card"><div class="teach-step"><span>02</span><div><h2>选择你的课堂形式</h2><p>两种都选时，知识点与例题共用，讲解保持一致。</p></div></div><div class="teach-format-picker">${[['pdf','file','PDF 讲义','整理知识，留给复习'],['video','camera','授课视频','跟着画面，听懂过程'],['both','graduation','视频＋讲义','讲解与复习，一次准备']].map(([v,i,title,desc])=>`<label class="teach-format ${d.output===v?'selected':''}"><input type="radio" name="output" value="${v}" ${d.output===v?'checked':''} ${disabled()}/>${icon(i)}<strong>${title}</strong><small>${desc}</small><span class="teach-radio-dot"></span></label>`).join('')}</div></section>
    <section class="teach-card"><div class="teach-step"><span>03</span><div><h2>${d.output==='video'?'安排教学内容':'定制讲义板块'}</h2><p>自由选择板块，调整顺序，也能加入自己的栏目。</p></div></div><div class="teach-block-choices">${Core.blocks.map(([id,title])=>`<label class="${d.blocks.some(b=>b.id===id)?'selected':''}"><input type="checkbox" data-teach-block="${id}" ${d.blocks.some(b=>b.id===id)?'checked':''} ${disabled()}/>${title}</label>`).join('')}</div>
    <div class="teach-block-order">${d.blocks.map((b,i)=>`<div><span class="teach-block-number">${String(i+1).padStart(2,'0')}</span><strong>${esc(b.title)}</strong><button type="button" data-action="teach-block-up" data-id="${esc(b.id)}" aria-label="上移${esc(b.title)}" ${busy()||i===0?'disabled':''}>↑</button><button type="button" data-action="teach-block-down" data-id="${esc(b.id)}" aria-label="下移${esc(b.title)}" ${busy()||i===d.blocks.length-1?'disabled':''}>↓</button><button type="button" data-action="teach-block-remove" data-id="${esc(b.id)}" aria-label="移除${esc(b.title)}" ${disabled()}>${icon('x')}</button></div>`).join('')}</div>
    <div class="teach-add-block"><input id="teach-custom-block" class="form-input" maxlength="24" aria-label="自定义板块名称" placeholder="例如：课堂讨论、拓展阅读" ${disabled()}/><button type="button" class="secondary-btn" data-action="teach-block-add" ${disabled()}>${icon('plus')}添加板块</button></div></section>
    <div class="teach-form-bottom"><p>${icon('shield')}生成的教学内容请核对后使用；不会自动发布。</p><button class="primary-btn" type="submit" ${disabled()}>${icon('sparkle')}${busy()?'正在准备课堂…':'生成我的课堂'}</button></div></form>
    <aside class="teach-aside"><section class="teach-budget-card"><span class="eyebrow">A LITTLE COST, A LOT TO LEARN</span><h2>轻量生成，<br/>把预算留在掌心。</h2><div id="teach-estimate">${estimateMarkup()}</div><p>这里估算内容与配音的调用费用。渲染、存储、检索和失败请求另计；不是账户扣费上限。</p><details><summary>调整单价与预算提醒 ${icon('settings')}</summary><div class="teach-price-fields">${[['input','输入 / 百万 Token'],['output','输出 / 百万 Token'],['speech','配音 / 万计费字符']].map(([k,label])=>`<label>${label}<span>¥ <input type="number" min="0" max="10000" step="0.1" data-teach-price="${k}" value="${d.prices[k]}" ${disabled()}/></span></label>`).join('')}<label>本次预算提醒<span>¥ <input id="teach-budget" type="number" min="0.01" max="1000" step="0.1" value="${d.budget}" ${disabled()}/></span></label></div><small>预填单价仅用于演示计算，请按服务商、地域和模型修改。汉字配音按 2 个计费字符估算。</small></details></section>
    <section class="teach-card teach-model-card"><span class="teach-aside-icon">${icon('sparkle')}</span><h3>沿用你的模型接入</h3><p>${esc(ai.connection().ready?ai.connection().name+' · '+ai.connection().model:'尚未配置。可以先体验示例，再连接自己的模型。')}</p><button class="text-link" data-route="ai-settings">模型设置 ${icon('arrow')}</button></section>
    <section class="teach-sample"><span>先看看，一节课的样子</span><h3>一次函数，<br/>从规律走进生活。</h3><p>内置内容体验，无模型调用费用。会使用当前所选板块和输出形式。</p><button class="secondary-btn" data-action="teach-demo" ${disabled()}>体验示例 ${icon('arrow')}</button></section></aside></div>`;}
  function estimateMarkup(){const d=draft(),e=Core.estimate(d,d.prices);return `<div class="teach-estimate-price">¥<strong>${e.total.toFixed(2)}</strong><span>/ 本次预估调用</span></div><div class="teach-budget-state ${e.total>d.budget?'over':''}">${icon(e.total>d.budget?'help':'check')}${e.total>d.budget?'超过当前提醒预算':'当前估算在预算内'} · 提醒线 ¥${d.budget.toFixed(2)}</div>`;}
  function refreshEstimate(){const el=$('#teach-estimate');if(el)el.innerHTML=estimateMarkup();}
  function sectionMarkup(s,i){return `<article class="teach-lesson-section"><div><span>${String(i+1).padStart(2,'0')}</span><h3>${esc(s.title)}</h3><button class="text-link" data-action="teach-edit-section" data-id="${esc(s.id)}" ${disabled()}>编辑 ${icon('settings')}</button></div><p>${esc(s.body)}</p></article>`;}
  function resultPage(){const r=result();if(!r)return `<div class="teach-empty">${icon('book')}<h2>下一节好课，从这里开始</h2><p>生成课堂或体验示例后，可以预览、编辑并导出成果。</p><button class="primary-btn" data-action="teach-tab" data-id="create">创建课堂 ${icon('arrow')}</button></div>`;
    const a=audio.get(r.id),v=video.get(r.id),pdf=r.config.output!=='video',hasVideo=r.config.output!=='pdf';
    return `<section class="teach-result-heading"><div><span class="teach-status-pill">${r.demo?'内置体验样例':'模型生成 · 待核对'}</span><h2>${esc(r.lesson.title)}</h2><p>${esc(r.lesson.audience)} · ${formatLabel(r.config.output)} · ${r.lesson.sections.length} 个教学板块</p></div><button class="secondary-btn" data-action="teach-download-text" ${disabled()}>${icon('download')}导出可编辑文本</button></section><p class="teach-source-note">${icon('book')}${esc(r.lesson.sourceNote)}</p>
    <div class="teach-result-layout"><div>${hasVideo?`<section class="teach-card teach-video-card"><div class="teach-panel-title"><div><span class="eyebrow">LESSON IN MOTION</span><h2>让知识，跟着画面展开</h2></div><span>镜头 ${slideIndex+1} / ${r.lesson.slides.length}</span></div><canvas id="teach-slide-canvas" width="1280" height="720" aria-label="授课镜头预览"></canvas><div class="teach-slide-nav">${r.lesson.slides.map((s,i)=>`<button class="${i===slideIndex?'active':''}" data-action="teach-slide" data-id="${i}" ${disabled()}>${String(i+1).padStart(2,'0')} ${esc(s.title)}</button>`).join('')}</div><div class="teach-slide-script"><strong>当前镜头旁白</strong><p>${esc(r.lesson.slides[slideIndex]?.narration||'')}</p><div><button class="text-link" data-action="teach-preview" ${disabled()}>${icon('music')}朗读当前镜头</button><button class="text-link" data-action="teach-edit-slide" data-id="${slideIndex}" ${disabled()}>编辑镜头 ${icon('settings')}</button></div></div>${v?`<div class="teach-exported-video"><strong>${v.hasAudio?'配音视频':'字幕视频'}已生成 · ${Math.round(v.duration)} 秒</strong><video controls src="${esc(v.url)}" aria-label="已生成的教学视频"></video><button class="primary-btn" data-action="teach-download-video">${icon('download')}下载 ${v.extension.toUpperCase()}</button></div>`:''}</section>`:''}
    ${pdf?`<section class="teach-card teach-handout"><div class="teach-panel-title"><div><span class="eyebrow">TAKE THE KNOWLEDGE WITH YOU</span><h2>这节课，留在纸上</h2></div><button class="secondary-btn" data-action="teach-export-pdf" ${disabled()}>${icon('download')}导出 PDF</button></div><div class="teach-handout-cover"><span>学屿 · 学习讲义</span><h2>${esc(r.lesson.title)}</h2><p>${esc(r.lesson.audience)} / ${r.lesson.sections.length} 个板块</p></div>${r.lesson.sections.map(sectionMarkup).join('')}</section>`:`<details class="teach-card"><summary>查看与编辑教学内容</summary>${r.lesson.sections.map(sectionMarkup).join('')}</details>`}</div>
    <aside class="teach-aside">${hasVideo?`<section class="teach-card teach-export-options"><h3>准备视频声音</h3><p>浏览器朗读仅供预览。导出配音视频前，请生成配音或导入自己的整课录音。</p><label class="form-label" for="teach-tts-model">语音模型 ID</label><input id="teach-tts-model" class="form-input" value="${esc(draft().ttsModel)}" placeholder="服务商提供的语音模型" maxlength="100" ${disabled()}/><label class="form-label" for="teach-voice">音色 ID</label><input id="teach-voice" class="form-input" value="${esc(draft().voice)}" placeholder="服务商提供的音色" maxlength="100" ${disabled()}/><button class="secondary-btn full-btn" data-action="teach-audio" ${disabled()}>${icon('music')}生成整课配音</button><small>使用当前模型接入的 /audio/speech 兼容接口，点击后才会调用并计费。</small><label class="teach-file-label">${icon('upload')}或导入整课录音<input id="teach-audio-file" type="file" accept="audio/*" ${disabled()}/></label>${a?`<div class="teach-audio-ready">${icon('check')}配音已就绪 · ${esc(a.name)}</div>`:''}<button class="primary-btn full-btn" data-action="teach-export-video" ${busy()||!a?'disabled':''}>${icon('camera')}生成配音视频</button><button class="text-link" data-action="teach-export-silent" ${disabled()}>生成仅字幕视频 ${icon('arrow')}</button><small>本机合成，耗时接近视频时长，请保持页面在前台。导出格式由浏览器决定。导入录音时应与整课旁白顺序一致；字幕时间按文字比例估算。</small></section>`:''}
    <section class="teach-card"><h3>本次生成记录</h3><div class="teach-record-line"><span>内容来源</span><strong>${r.demo?'内置示例':esc(r.model)}</strong></div><div class="teach-record-line"><span>输入 Token</span><strong>${r.usage?.input??'未返回'}</strong></div><div class="teach-record-line"><span>输出 Token</span><strong>${r.usage?.output??'未返回'}</strong></div><p class="teach-small-note">${r.demo?'示例没有调用模型。':r.usage?.input==null?'接口未返回用量，无法核算本次文本费用。':'实际扣费以服务商账单为准。'}重试和失败请求可能另有费用。</p><button class="text-link" data-action="teach-tab" data-id="create">调整下一课 ${icon('arrow')}</button></section></aside></div>`;
  }
  function historyPage(){const rows=list();return `<div class="teach-library-header"><h2>把准备过的好课留下来</h2><p>按学校保存在当前浏览器，最多保留最近 6 课。录音和视频文件只在本页内存中，刷新后需重新准备。</p></div>${rows.length?`<div class="teach-library-grid">${rows.map(r=>`<article class="teach-card teach-library-item"><div class="teach-library-art">${icon(r.config.output==='pdf'?'file':'graduation')}<span>${formatLabel(r.config.output)}</span></div><span class="teach-status-pill">${r.demo?'体验样例':'我的课堂'}</span><h3>${esc(r.lesson.title)}</h3><p>${esc(r.lesson.audience)} · ${r.lesson.sections.length} 个板块</p><small>${esc(new Date(r.created).toLocaleDateString('zh-CN',{timeZone:'Asia/Shanghai'}))}</small><div><button class="primary-btn" data-action="teach-open" data-id="${esc(r.id)}" ${disabled()}>继续编辑 ${icon('arrow')}</button><button class="icon-btn" data-action="teach-delete" data-id="${esc(r.id)}" aria-label="删除${esc(r.lesson.title)}" ${disabled()}>${icon('x')}</button></div></article>`).join('')}</div>`:'<div class="teach-empty"><h3>还没有保存的课堂</h3><p>生成的课程会自动保存在这里。</p></div>'}`;}
  function page(){return `${heading('YOUR KNOWLEDGE, YOUR CLASSROOM','AI 学堂','给一个主题，让知识成为可讲解、可复习的一节课。',`<button class="secondary-btn" data-route="features">全部功能 ${icon('arrow')}</button>`)}<section class="teach-hero"><div><span class="teach-hero-label">独立学习工作台 / TEACHING STUDIO</span><h2>把一个知识点，<br/>讲清楚。</h2><p>选好主题，安排内容。<br/>从一份讲义，到一段属于你的微课。</p><div><span>${icon('file')}自由定制讲义</span><span>${icon('camera')}轻量授课视频</span><span>${icon('leaf')}按需生成</span></div></div><div class="teach-hero-art" aria-hidden="true"><div class="teach-art-sheet"><span>LESSON NOTES</span><b>y = kx + b</b><i></i><i></i><i></i><small>从理解，走向掌握。</small></div><div class="teach-art-video"><span>01 / 05</span><b>▶</b><div></div></div><span class="teach-art-spark">✦</span></div></section><div class="teach-tabs" role="tablist" aria-label="教学工作台">${[['create','创建课堂'],['result','课堂成果'],['library','我的课堂']].map(([id,title])=>`<button role="tab" aria-selected="${tab===id}" class="${tab===id?'active':''}" data-action="teach-tab" data-id="${id}">${title}${id==='library'?`<span>${list().length}</span>`:''}</button>`).join('')}</div>${error?`<div class="teach-error" role="alert">${icon('help')}<span>${esc(error)}</span><button data-action="teach-clear-error" aria-label="关闭提示">${icon('x')}</button></div>`:''}${busy()?`<div class="teach-progress" role="status"><span class="teach-spinner"></span><span id="teach-progress-label">${esc(progress)}</span><button data-action="teach-cancel">停止</button></div>`:''}<div class="teach-tab-panel" role="tabpanel">${tab==='create'?form():tab==='result'?resultPage():historyPage()}</div>${footer()}`;}
  function start(kind,message){if(operation)throw new Error('请先等待或停止当前任务。');const op={id:++generation,school:school().id,controller:new AbortController(),kind};operation=op;error='';progress=message;return op;}
  const active=op=>operation===op&&op.school===school().id&&!op.controller.signal.aborted;
  function finish(op){if(operation===op){operation=null;progress='';rerender();}}
  function fail(e,op){if(operation!==op||op.school!==school().id)return;error=op.controller.signal.aborted?'任务已停止；已发出的服务商请求仍可能计费。':ai.redact(e.message||'任务未完成，请稍后重试。');}
  async function generate(){let op;try{
    const d=draft();Core.validate(d);if(!ai.connection().ready){error='请先连接自己的模型，或点击“体验示例”查看完整流程。';rerender();return;}
    if(Core.estimate(d,d.prices).total>d.budget)throw new Error('当前估算超过提醒预算，请缩短内容或调整预算后再生成。');
    const config=JSON.parse(JSON.stringify(d));op=start('content','正在编排知识点、例题与课堂镜头…');rerender();
    const response=await ai.generateTeaching(Core.messages(config),{signal:op.controller.signal,maxTokens:Math.min(10000,2000+config.blocks.length*600+(config.output==='pdf'?0:2200))});
    if(!active(op))return;const lesson=Core.parseLesson(response.content,config);resetMedia();const record={id:crypto.randomUUID(),created:Date.now(),lesson,config:{...config,material:''},usage:response.usage,model:ai.connection().model,demo:false};
    results.set(school().id,record);remember(record);tab='result';slideIndex=0;toast('课堂内容已生成，可以核对、编辑和导出。');
  }catch(e){if(op)fail(e,op);else{error=e.message;rerender();}}finally{if(op)finish(op);}}
  function demo(){if(busy())return;try{Core.validate({...draft(),topic:'一次函数'});resetMedia();const config=JSON.parse(JSON.stringify({...draft(),topic:'一次函数',audience:'初中'}));const record={id:crypto.randomUUID(),created:Date.now(),lesson:Core.demo(config),config:{...config,material:''},model:'内置示例',demo:true,usage:{input:0,output:0}};results.set(school().id,record);remember(record);tab='result';slideIndex=0;error='';rerender();}catch(e){error=e.message;rerender();}}
  function reorder(id,step){if(busy())return;const items=draft().blocks,i=items.findIndex(b=>b.id===id);if(i<0||i+step<0||i+step>=items.length)return;items.splice(i+step,0,items.splice(i,1)[0]);rerender();}
  function editSection(id){if(busy())return;const r=result(),s=r?.lesson.sections.find(s=>s.id===id);if(!s)return;showModal(`<div class="modal-content"><span class="modal-tag">编辑教学板块</span><h2>${esc(s.title)}</h2><form id="teach-section-form" data-id="${esc(id)}"><label class="form-label" for="teach-section-body">正文</label><textarea id="teach-section-body" name="body" class="form-input" rows="12" maxlength="6000" required>${esc(s.body)}</textarea><button class="primary-btn full-btn" type="submit">保存修改 ${icon('check')}</button></form></div>`);}
  function editSlide(id){if(busy())return;const s=result()?.lesson.slides[Number(id)];if(!s)return;showModal(`<div class="modal-content"><span class="modal-tag">编辑第 ${Number(id)+1} 个镜头</span><h2>让讲解更贴近你的课堂</h2><form id="teach-slide-form" data-id="${Number(id)}"><label class="form-label" for="teach-slide-title">镜头标题</label><input id="teach-slide-title" name="title" class="form-input" value="${esc(s.title)}" maxlength="70" required/><label class="form-label" for="teach-slide-bullets">画面要点（每行一条，最多 5 条，每条最多 90 字）</label><textarea id="teach-slide-bullets" name="bullets" class="form-input" rows="5" required>${esc(s.bullets.join('\n'))}</textarea><label class="form-label" for="teach-slide-narration">讲解旁白</label><textarea id="teach-slide-narration" name="narration" class="form-input" rows="6" maxlength="900" required>${esc(s.narration)}</textarea><p class="form-note">保存镜头后，原配音和已合成的视频将清除，需要重新准备。讲义内容可分别编辑，请注意保持一致。</p><button class="primary-btn full-btn" type="submit">保存镜头 ${icon('check')}</button></form></div>`);}
  async function exportPDF(){if(busy()||!result())return;const op=start('pdf','正在排版讲义并导出 PDF…');rerender();try{await document.fonts.ready;if(!active(op))return;Media.download(Media.makePDF(Media.pdfPages(result().lesson)),result().lesson.title+'.pdf');toast('PDF 讲义已导出。');}catch(e){fail(e,op);}finally{finish(op);}}
  async function generateAudio(){let op;try{if(!result()||busy())return;const d=draft();if(!d.ttsModel.trim()||!d.voice.trim())throw new Error('请填写语音模型和音色 ID，或直接导入自己的录音。');op=start('audio','正在生成整课配音…');rerender();const r=result(),text=r.lesson.slides.map(s=>s.narration).join('\n');const blob=await ai.generateSpeech({text,model:d.ttsModel,voice:d.voice,signal:op.controller.signal});if(active(op)){clearVideo(r.id);audio.set(r.id,{blob,name:'服务商生成的配音'});toast('配音已就绪，可以合成配音视频。');}}catch(e){if(op)fail(e,op);else{error=e.message;rerender();}}finally{if(op)finish(op);}}
  async function exportVideo(silent=false){let op;try{const r=result();if(!r||busy())return;const a=audio.get(r.id);if(!silent&&!a)throw new Error('请先准备配音，或选择“生成仅字幕视频”。');window.speechSynthesis?.cancel();op=start('video','正在本机合成视频 · 0% · 请保持页面在前台');rerender();await document.fonts.ready;const output=await Media.recordVideo(r.lesson,{audioBlob:silent?null:a.blob,signal:op.controller.signal,silentSeconds:Number(r.config.minutes)*60/r.lesson.slides.length,onProgress:value=>{if(active(op)){progress=`正在本机合成${silent?'字幕':'配音'}视频 · ${value}% · 请保持页面在前台`;const el=$('#teach-progress-label');if(el)el.textContent=progress;}}});if(active(op)){const previous=video.get(r.id);if(previous)URL.revokeObjectURL(previous.url);video.set(r.id,{...output,url:URL.createObjectURL(output.blob),hasAudio:!silent});toast('视频已合成，可以预览和下载。');}}catch(e){if(op)fail(e,op);else{error=e.message;rerender();}}finally{if(op)finish(op);}}
  function onInput(event){const el=event.target;if(busy())return;const d=draft(),names={'teach-topic':'topic','teach-objectives':'objectives','teach-material':'material','teach-tts-model':'ttsModel','teach-voice':'voice'};if(names[el.id]){d[names[el.id]]=el.value;refreshEstimate();}if(el.dataset.teachPrice){const n=Number(el.value);if(Number.isFinite(n)&&n>=0&&n<=10000)d.prices[el.dataset.teachPrice]=n;refreshEstimate();}if(el.id==='teach-budget'){const n=Number(el.value);if(Number.isFinite(n)&&n>0&&n<=1000)d.budget=n;refreshEstimate();}}
  async function onChange(event){const el=event.target;if(busy())return;const d=draft();if(el.id==='teach-audience')d.audience=el.value;if(el.id==='teach-minutes'){d.minutes=Number(el.value);refreshEstimate();}if(el.name==='output'){d.output=el.value;rerender();}if(el.dataset.teachBlock){const id=el.dataset.teachBlock;if(el.checked){if(d.blocks.length>=14){el.checked=false;toast('最多 14 个教学板块');return;}d.blocks.push({id,title:Core.blocks.find(b=>b[0]===id)[1]});}else d.blocks=d.blocks.filter(b=>b.id!==id);rerender();}
    if(el.id==='teach-source-file'){const file=el.files[0],sid=school().id;if(!file)return;try{if(!/\.(txt|md)$/i.test(file.name)||file.size>100*1024)throw new Error('请选择不超过 100 KB 的 TXT 或 MD 文件。');const value=await file.text();if(value.length>12000)throw new Error('资料超过 12000 字，请精简后导入。');if(sid!==school().id)return;d.material=value;rerender();toast('文字资料已导入。');}catch(e){error=e.message;rerender();}}
    if(el.id==='teach-audio-file'){const file=el.files[0],r=result();if(!file||!r)return;if(!file.type.startsWith('audio/')||file.size>20*1024*1024){error='请选择不超过 20 MB 的音频文件。';rerender();return;}clearVideo(r.id);audio.set(r.id,{blob:file,name:file.name});rerender();toast('录音已准备好。');}
  }
  function onSubmit(event){const f=event.target;if(f.id==='teach-create-form'){event.preventDefault();generate();}if(f.id==='teach-section-form'){event.preventDefault();if(busy())return;const r=result(),s=r?.lesson.sections.find(s=>s.id===f.dataset.id),body=f.elements.body.value.trim();if(!s||!body)return;s.body=body.slice(0,6000);remember(r);closeModal();rerender();toast('板块内容已保存。');}if(f.id==='teach-slide-form'){event.preventDefault();if(busy())return;const r=result(),s=r?.lesson.slides[Number(f.dataset.id)];if(!s)return;const title=f.elements.title.value.trim(),bullets=f.elements.bullets.value.split('\n').map(s=>s.trim()).filter(Boolean),narration=f.elements.narration.value.trim();if(!title||!narration||!bullets.length||bullets.length>5||bullets.some(s=>s.length>90)){toast('请检查标题、旁白和要点的数量、长度。');return;}resetMedia();Object.assign(s,{title:title.slice(0,70),bullets,narration:narration.slice(0,900)});remember(r);closeModal();rerender();toast('镜头已更新，请重新准备配音。');}}
  function afterRender(){const r=result(),canvas=$('#teach-slide-canvas');if(canvas&&r?.lesson.slides.length)Media.drawSlide(canvas,r.lesson.slides[slideIndex]||r.lesson.slides[0],{index:slideIndex,total:r.lesson.slides.length,progress:1});}
  function schoolChanged(){operation?.controller.abort();operation=null;error='';progress='';tab='create';slideIndex=0;window.speechSynthesis?.cancel();}
  const actions={
    'teach-tab':id=>{if(!['create','result','library'].includes(id))return;window.speechSynthesis?.cancel();tab=id;rerender();},'teach-demo':demo,
    'teach-clear-error':()=>{error='';rerender();},'teach-cancel':()=>{if(operation){operation.controller.abort();progress='正在停止任务…';const el=$('#teach-progress-label');if(el)el.textContent=progress;}},
    'teach-block-up':id=>reorder(id,-1),'teach-block-down':id=>reorder(id,1),'teach-block-remove':id=>{if(busy())return;draft().blocks=draft().blocks.filter(b=>b.id!==id);rerender();},
    'teach-block-add':()=>{if(busy())return;const title=$('#teach-custom-block')?.value.trim();if(!title){toast('请填写自定义板块名称');return;}if(draft().blocks.length>=14){toast('最多 14 个板块');return;}if(draft().blocks.some(b=>b.title===title)){toast('这个板块已存在');return;}draft().blocks.push({id:'custom-'+crypto.randomUUID(),title:title.slice(0,24)});rerender();},
    'teach-edit-section':editSection,'teach-edit-slide':editSlide,
    'teach-slide':id=>{if(busy())return;const index=Number(id);if(Number.isInteger(index)&&index>=0&&index<(result()?.lesson.slides.length||0)){window.speechSynthesis?.cancel();slideIndex=index;rerender();}},
    'teach-preview':()=>{if(busy()||!result())return;if(!window.speechSynthesis){toast('当前浏览器不支持朗读，请导入录音。');return;}window.speechSynthesis.cancel();const utterance=new SpeechSynthesisUtterance(result().lesson.slides[slideIndex].narration);utterance.lang='zh-CN';utterance.rate=0.95;window.speechSynthesis.speak(utterance);toast('正在朗读当前镜头，仅用于预览。');},
    'teach-export-pdf':exportPDF,'teach-audio':generateAudio,'teach-export-video':()=>exportVideo(false),'teach-export-silent':()=>exportVideo(true),
    'teach-download-video':()=>{const r=result(),v=r&&video.get(r.id);if(v)Media.download(v.blob,r.lesson.title+(v.hasAudio?'':'-字幕版')+'.'+v.extension);},
    'teach-download-text':()=>{const r=result();if(!r||busy())return;const content='# '+r.lesson.title+'\n\n'+r.lesson.sourceNote+'\n\n'+r.lesson.sections.map(s=>'## '+s.title+'\n\n'+s.body).join('\n\n')+(r.lesson.slides.length?'\n\n# 视频分镜与旁白\n\n'+r.lesson.slides.map((s,i)=>`## ${i+1}. ${s.title}\n\n${s.bullets.map(b=>'- '+b).join('\n')}\n\n旁白：${s.narration}`).join('\n\n'):'');Media.download(new Blob([content],{type:'text/markdown;charset=utf-8'}),r.lesson.title+'.md');},
    'teach-open':id=>{if(busy())return;const record=list().find(r=>r.id===id);if(!record)return;try{const copy=JSON.parse(JSON.stringify(record));copy.lesson=Core.parseLesson(JSON.stringify(copy.lesson),{...copy.config,material:''});copy.lesson.sourceNote=String(record.lesson.sourceNote||'保存的课堂，请核对后使用。').slice(0,300);results.set(school().id,copy);slideIndex=0;tab='result';error='';rerender();}catch{error='这份课堂记录格式不完整，请重新生成。';rerender();}},
    'teach-delete':id=>{if(busy())return;history[school().id]=list().filter(r=>r.id!==id);if(result()?.id===id){resetMedia();results.delete(school().id);}saveHistory();rerender();toast('已从本地课堂记录移除。');}
  };
  return {pages:{teaching:page},entry,actions,onInput,onChange,onSubmit,afterRender,schoolChanged,routeChanged:route=>{if(route!=='teaching')window.speechSynthesis?.cancel();}};
};
